import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    k = int(data[1 + n])
    need = set(data[2 + n:2 + n + k])
    cnt = {}
    have = 0
    best = None
    l = 0
    for r in range(n):
        w = words[r]
        if w in need:
            c = cnt.get(w, 0) + 1
            cnt[w] = c
            if c == 1:
                have += 1
        while have == len(need):
            if best is None or r - l < best[1] - best[0]:
                best = (l, r)
            w2 = words[l]
            if w2 in need:
                cnt[w2] -= 1
                if cnt[w2] == 0:
                    have -= 1
            l += 1
    if best is None:
        print('')
    else:
        print(' '.join(words[best[0]:best[1] + 1]))

main()

